from pagination import paginate


def test_page_two_size_two_returns_third_and_fourth():
    # Literal issue example: range(1, 8) is [1, 2, 3, 4, 5, 6, 7].
    assert paginate(list(range(1, 8)), 2, 2) == [3, 4]


def test_first_page_returns_first_slice():
    assert paginate(list(range(1, 8)), 1, 2) == [1, 2]


def test_last_full_page():
    assert paginate(list(range(1, 8)), 3, 2) == [5, 6]


def test_partial_final_page():
    assert paginate(list(range(1, 8)), 4, 2) == [7]


def test_beyond_last_page_returns_empty_list():
    assert paginate(list(range(1, 8)), 5, 2) == []
    assert paginate(list(range(1, 8)), 100, 2) == []


def test_empty_items_returns_empty_list():
    assert paginate([], 1, 2) == []


def test_invalid_page_returns_empty_list():
    assert paginate([1, 2], 0, 2) == []
    assert paginate([1, 2], -1, 2) == []


def test_invalid_page_size_returns_empty_list():
    assert paginate([1, 2], 1, 0) == []
    assert paginate([1, 2], 1, -3) == []


def test_result_is_a_list_type():
    result = paginate(list(range(1, 8)), 2, 2)
    assert isinstance(result, list)
    assert result == [3, 4]


def test_page_size_one_walks_items():
    assert paginate(list(range(1, 8)), 1, 1) == [1]
    assert paginate(list(range(1, 8)), 7, 1) == [7]
    assert paginate(list(range(1, 8)), 8, 1) == []


def test_page_size_larger_than_items():
    assert paginate(list(range(1, 8)), 1, 100) == [1, 2, 3, 4, 5, 6, 7]
    assert paginate(list(range(1, 8)), 2, 100) == []
